    Numeric identifiers sort below alphanumeric ones. Numeric identifiers
    compare as integers, alphanumeric ones compare in ASCII order.
    """
    ids = []
    for ident in pre.split("."):
        if _is_number(ident):
            ids.append((0, int(ident), ""))
        else:
            ids.append((1, 0, ident))
    return tuple(ids)


def _sort_key(version):
    # Build metadata after '+' is ignored for ordering.
    main = version.split("+", 1)[0]
    if "-" in main:
        core, pre = main.split("-", 1)
    else:
        core, pre = main, None

    major, minor, patch = (int(part) for part in core.split("."))

    if pre is None:
        # A normal release is higher than any pre-release of the same version.
        return (major, minor, patch, 1, ())
    return (major, minor, patch, 0, _pre_release_key(pre))


def sort_versions(vs):
    """Return the version strings in vs sorted lowest first.

    Versions that compare equal keep their input order, because Python's
    sort is stable.
